    local function BNValid(o) return o ~= nil and slua and slua.isValid and slua.isValid(o) end
    local function BNv2(x, y)
        if BN_FVector2D then return BN_FVector2D(x, y) end
        return { X = x, Y = y }
    end
    local function BNcol(r, g, b, a)
        if BN_FLinearColor then return BN_FLinearColor(r, g, b, a) end
        return { R = r, G = g, B = b, A = a }
