    -- ── Bridge to the rest of 6.lua ─────────────────────────────────
    function BannerESP.GetCanvas()
        if PlayerMapMarker and PlayerMapMarker.InitESPCanvas then
            if PlayerMapMarker.InitESPCanvas() then return PlayerMapMarker.ESPCanvas end
        end
        return nil
    end

    function BannerESP.GetPPU()             -- screen pixels per canvas unit
        local sx = (PlayerMapMarker and PlayerMapMarker._CanvasScaleX) or 1
        if type(sx) ~= "number" or sx <= 0 then sx = 1 end
        return 1 / sx
    end

    function BannerESP.GetCounterOpacity()  -- 0..1 live from the menu config
        local v = tonumber(_G.LexusConfig and _G.LexusConfig.CounterOpacity) or 100
        if v < 0 then v = 0 elseif v > 100 then v = 100 end
        return v / 100
    end

    function BannerESP.GetCounterTextPct()  -- keep text inside the counter at any size
        local cfg = _G.LexusConfig or {}
        local l = tonumber(cfg.CounterLength) or 100
        local w = tonumber(cfg.CounterWidth) or 140
        if l < 1 then l = 1 end
        if w < 1 then w = 1 end
        return math.min(l, w)
    end

    function BannerESP.BNCell()             -- vertical canvas units per data unit
        local pct = tonumber(_G.LexusConfig and _G.LexusConfig.CounterWidth) or 140
        return (BannerESP.BN_SCALE or 1.0) * (pct / 100)
             / (BannerESP.TILE_DESIGN_PPU or 1.6875)
    end

    function BannerESP.BNCellX()            -- horizontal canvas units per data unit
        local pct = tonumber(_G.LexusConfig and _G.LexusConfig.CounterLength) or 100
        return ((BannerESP.BN_SCALE or 1.0) * (BannerESP.BN_W_SCALE or 1.0) * (pct / 100))
             / (BannerESP.TILE_DESIGN_PPU or 1.6875)
    end

    function BannerESP.BannerOk(rb)
        local now = BannerESP._now or 0
        local dt  = now - (rb.vt or -1e9)
        if rb.ve == BannerESP._vep and dt >= 0 and dt < BannerESP.WCheckEvery then
            return rb.vok
        end
        local ok = (rb.probe == nil) or BNValid(rb.probe)
        rb.ve, rb.vt, rb.vok = BannerESP._vep, now, ok
        return ok
    end

    function BannerESP.BannerDestroy()
        local rb = BannerESP.Banner
        BannerESP.Banner = nil
        if not rb then return end
        -- single-image path
        if rb.Img and BNValid(rb.Img) then
            pcall(function() rb.Img:RemoveFromParent(); rb.Img:ConditionalBeginDestroy() end)
        end
        rb.Img, rb.ImgSlot = nil, nil
        if not rb.Layers then return end
        for _, ly in pairs(rb.Layers) do
            for _, p in ipairs(ly.parts) do
                local w = p.ln and p.ln.Widget
                if w and BNValid(w) then
                    pcall(function() w:RemoveFromParent(); w:ConditionalBeginDestroy() end)
                end
            end
        end
    end

    function BannerESP.BannerHideLayer(ly)
        if not ly or not ly.shown then return end
        ly.shown = false
        for _, p in ipairs(ly.parts) do
            local w = p.ln and p.ln.Widget
            if w and BNValid(w) then
                pcall(function() w:SetWidgetVisibility(BN_HID) end)
                p.ln.hidden = true
            end
        end
    end

    function BannerESP.BannerHide()
        local rb = BannerESP.Banner
        if not rb or rb.hidden then return end
        rb.hidden = true
        if rb.Img and BNValid(rb.Img) then
            pcall(function() rb.Img:SetWidgetVisibility(BN_HID) end)
            rb.Img.hidden = true
        end
        if rb.Layers then
            for _, ly in pairs(rb.Layers) do BannerESP.BannerHideLayer(ly) end
        end
    end

    function BannerESP.BannerNewRect(color, z)
        local canvas = BannerESP.GetCanvas()
        if not BNValid(canvas) then return nil end
        local border = nil
        pcall(function() border = CGame:NewObjectFromPath("/Script/UMG.Border", canvas) end)
        if not BNValid(border) then return nil end
        pcall(function()
            border:SetBrushColor(color)
            border:SetWidgetVisibility(BN_HID)
        end)
        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(border) end)
        if not slot then
            pcall(function() border:RemoveFromParent() end)
            return nil
        end
        pcall(function() slot:SetAutoSize(false); slot:SetZOrder(z or 30) end)
        return { Widget = border, Slot = slot, hidden = true }
    end

    function BannerESP.BannerPlace(d, x1, y1, x2, y2, ppu)
        if not d or not d.Slot or not BNValid(d.Widget) then return false end
        local a = math.floor(x1 * ppu + 0.5)
        local b = math.floor(y1 * ppu + 0.5)
        local c = math.floor(x2 * ppu + 0.5)
        local e = math.floor(y2 * ppu + 0.5)
        if c <= a then c = a + 1 end
        if e <= b then e = b + 1 end
        if d.fx1 == a and d.fy1 == b and d.fx2 == c and d.fy2 == e then return true end
        local ok = pcall(function()
            d.Slot:SetPosition(BNv2(a / ppu, b / ppu))
            d.Slot:SetSize    (BNv2((c - a) / ppu, (e - b) / ppu))
        end)
        if ok then d.fx1, d.fy1, d.fx2, d.fy2 = a, b, c, e end
        return ok
    end

    -- Opacity is applied lazily: only when the config value actually changes,
    -- so the per-frame place/position path stays allocation-free.
    function BannerESP.BannerApplyOpacity(rb)
        if rb.lastOp == BannerESP.opCur then return end
        local op = BannerESP.GetCounterOpacity()
        rb.lastOp = op
        BannerESP.opCur = op
        if not rb.Layers then return end
        for _, ly in pairs(rb.Layers) do
            local base = ly.base or 1
            for _, p in ipairs(ly.parts) do
                local w = p.ln and p.ln.Widget
                local c  = p.ln and p.ln.col
                if w and c and BNValid(w) then
                    pcall(function() w:SetBrushColor(BNcol(c.r, c.g, c.b, c.a * base * op)) end)
                end
            end
        end
    end

    function BannerESP.BannerShowLayer(ly, X, Y, cellX, cellY, ppu)
        if not ly then return end
        if ly.shown and ly.gx == X and ly.gy == Y and ly.gcx == cellX and ly.gcy == cellY and ly.gp == ppu then return end
        ly.shown = true
        ly.gx, ly.gy, ly.gcx, ly.gcy, ly.gp = X, Y, cellX, cellY, ppu
        for _, p in ipairs(ly.parts) do
            local ln = p.ln
            if BannerESP.BannerPlace(ln,
                X + p.x1 * cellX, Y + p.y1 * cellY,
                X + p.x2 * cellX, Y + p.y2 * cellY, ppu)
            then
                if ln.hidden ~= false then
                    pcall(function() ln.Widget:SetWidgetVisibility(BN_VIS) end)
                    ln.hidden = false
                end
            end
        end
    end

    -- ── Single-texture capsule: download + Image widget ──────────────
    local function BNIsTexture(o)
        if o == nil then return false end
        -- A UTexture2D is a UObject: slua.isValid should accept it.
        if BNValid(o) then return true end
        -- Some engines hand back a non-slate wrapper; accept if it survives
        -- a class-name probe that mentions "texture".
        local ok, tn = pcall(function()
            local cl = o.GetClass and o:GetClass()
            return cl and cl:GetName()
        end)
        if ok and tn and tostring(tn):lower():find("texture") then return true end
        return false
    end

    -- Try every known engine path to turn a URL into a UTexture2D.
    function BannerESP.TryLoadImage(url, onOk)
        local done = false
        local function finish(tex)
            if done then return end
            if tex ~= nil then done = true; onOk(tex) end
        end
        -- 1) UMG AsyncTaskDownloadImage (simplest, used by 3.lua first)
        pcall(function()
            local cls = import("AsyncTaskDownloadImage") or import("/Script/UMG.AsyncTaskDownloadImage")
            if cls and cls.DownloadImage then
                local task = cls.DownloadImage(url)
                if task and task.OnSuccess then
                    task.OnSuccess:Add(function(tex) finish(tex) end)
                    if task.OnFail then task.OnFail:Add(function() end) end
                end
            end
        end)
        -- 2) game image_download_mgr HTTP wrapper
        pcall(function()
            local mgr = nil
            local MM = _G.ModuleManager or package.loaded["GameLua.GameCore.Module.ModuleManager"]
            if not MM then pcall(function() MM = require("GameLua.GameCore.Module.ModuleManager") end) end
            if MM and MM.GetModule and MM.CommonModuleConfig then
                mgr = MM.GetModule(MM.CommonModuleConfig.image_download_mgr)
            end
            if not mgr then pcall(function() mgr = require("client.slua.logic.image_download.image_download_mgr") end) end
            if mgr and mgr.DownloadImageByHttpWrapper then
                mgr:DownloadImageByHttpWrapper(url, function(tex) finish(tex) end, function() end)
            end
        end)
        -- 3) ui_framework util SetTexture (sync=false)
        pcall(function()
            local util = package.loaded["client.slua_ui_framework.util"]
            if not util then pcall(function() util = require("client.slua_ui_framework.util") end) end
            if util and util.SetTexture then
                util.SetTexture(nil, url, { sync = false, onDownloadSuccess = function(tex) finish(tex) end })
            end
        end)
        -- 4) plain asset load if the URL is actually a local path
        pcall(function()
            local tex = nil
            if CGame and CGame.LoadObject then tex = CGame:LoadObject(url) end
            if tex then finish(tex) end
        end)
    end

    -- Kick off (at most one at a time) loading of the capsule texture.
    function BannerESP.EnsureImage()
        local cfg = BannerESP.BN_IMG
        if not cfg or not cfg.enabled then return nil end
        if BannerESP._imgTex and BNIsTexture(BannerESP._imgTex) then return BannerESP._imgTex end
        BannerESP._imgTex = nil
        local now = os.clock and os.clock() or 0
        if BannerESP._imgTried then
            if now < (BannerESP._imgDeadline or 0) then return nil end
            BannerESP._imgFailed = false
        end
        local urls = cfg.URLs or {}
        local i = 0
        local function tryNext()
            i = i + 1
            local url = urls[i]
            if not url then
                BannerESP._imgTried   = true
                BannerESP._imgFailed  = true
                BannerESP._imgDeadline = (os.clock and os.clock() or 0) + 2.0
                return
            end
            BannerESP.TryLoadImage(url, function(tex)
                if BNIsTexture(tex) then
                    BannerESP._imgTex    = tex
                    BannerESP._imgTried  = true
                    BannerESP._imgFailed = false
                else
                    tryNext()
                end
            end)
        end
        BannerESP._imgTried = true
        tryNext()
        return BannerESP._imgTex
    end

    function BannerESP.BannerCreate()
        local canvas = BannerESP.GetCanvas()
        if not BNValid(canvas) then return nil end
        local rb = { Layers = {}, hidden = true, ready = false, bi = 1, bj = 1 }
        BannerESP.Banner = rb
        return rb
    end

    -- ── Single Image widget (texture path) ───────────────────────────
    function BannerESP.ImageCreate(rb)
        local canvas = BannerESP.GetCanvas()
        if not BNValid(canvas) then return nil end
        local img = nil
        pcall(function() img = CGame:NewObjectFromPath("/Script/UMG.Image", canvas) end)
        if not BNValid(img) then return nil end
        pcall(function()
            local a = BannerESP.GetCounterOpacity()
            if BN_FLinearColor then img:SetColorAndOpacity(BN_FLinearColor(1, 1, 1, a))
            else img:SetColorAndOpacity({ R = 1, G = 1, B = 1, A = a }) end
            img:SetWidgetVisibility(BN_HID)
        end)
        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(img) end)
        if not slot then pcall(function() img:RemoveFromParent() end); return nil end
        pcall(function()
            slot:SetAutoSize(false)
            slot:SetAlignment(BNv2(0.0, 0.0))   -- (X,Y) is top-left origin
            slot:SetZOrder(1000)
        end)
        rb.Img  = img
        rb.ImgSlot = slot
        rb.ImgShown = false
        rb.ImgApplied = false
        rb.ImgSet = false
        return img
    end

    -- Position + size the single Image from the ribbon aspect.
    function BannerESP.ImageApply(rb, X, Y, cellX, cellY, ppu)
        local img, slot = rb.Img, rb.ImgSlot
        if not BNValid(img) or not slot then return false end
        -- Only the texture path uses this; if it isn't loaded yet, retry.
        local tex = BannerESP._imgTex
        if not (tex and BNIsTexture(tex)) then return false end
        if not rb.ImgSet then
            local ok = pcall(function() img:SetBrushFromTexture(tex, false) end)
            if not ok then return false end
            rb.ImgSet = true
        end
        -- Scale off the LEGACY dimensions so COUNTER LENGTH/WIDTH feel consistent
        -- with the old capsule. LENGTH scales width, WIDTH scales height independently.
        local cfgImg = BannerESP.BN_IMG or {}
        local mul    = tonumber(cfgImg.sizeMul) or 1.0
        local wCanvas = (BannerESP.BN_W_DP or 640) * cellX * mul
        local hCanvas = (BannerESP.BN_H_DP or 92) * cellY * mul
        -- clamp to rounded pixel grid for crisp placement
        local a = math.floor(X * ppu + 0.5)
        local b = math.floor(Y * ppu + 0.5)
        local c = math.floor((X + wCanvas) * ppu + 0.5)
        local e = math.floor((Y + hCanvas) * ppu + 0.5)
        if c <= a then c = a + 1 end
        if e <= b then e = b + 1 end
        if rb.ImgFx1 == a and rb.ImgFy1 == b and rb.ImgFx2 == c and rb.ImgFy2 == e then
            -- size unchanged
        else
            pcall(function()
                slot:SetPosition(BNv2(a / ppu, b / ppu))
                slot:SetSize(BNv2((c - a) / ppu, (e - b) / ppu))
            end)
            rb.ImgFx1, rb.ImgFy1, rb.ImgFx2, rb.ImgFy2 = a, b, c, e
        end
        -- opacity
        local op = BannerESP.GetCounterOpacity()
        if rb.ImgOp ~= op then
            rb.ImgOp = op
            pcall(function()
                if BN_FLinearColor then img:SetColorAndOpacity(BN_FLinearColor(1, 1, 1, op))
                else img:SetColorAndOpacity({ R = 1, G = 1, B = 1, A = op }) end
            end)
        end
        if rb.Img.hidden ~= false then
            pcall(function() img:SetWidgetVisibility(BN_VIS) end)
            rb.Img.hidden = false
        end
        -- expose the drawn rectangle so labels can be placed inside it
        rb.ImgRect = { x = X, y = Y, w = wCanvas, h = hCanvas }
        return true
    end

    function BannerESP.BannerBuild(rb, X, Y, cellX, cellY, ppu)
        local data, order = BannerESP.BN_LAYERS, BannerESP.BN_LAYER_ORDER
        local budget = BannerESP.BN_BUILD_STEP or 40
        while budget > 0 do
            local name = order[rb.bi]
            if not name then rb.ready = true; return end
            local layer = data[name]
            local ly = rb.Layers[name]
            if not ly then
                local cols, pcol = {}, {}
                for i, e in ipairs(layer.pal) do
                    pcol[i] = { r = e[1], g = e[2], b = e[3], a = e[4] or 1 }
                    cols[i] = BNcol(e[1], e[2], e[3], (e[4] or 1) * (layer.base or 1) * BannerESP.GetCounterOpacity())
                end
                ly = { parts = {}, cols = cols, pcol = pcol, shown = false, base = layer.base }
                rb.Layers[name] = ly
            end
            local r = layer.r
            local nrect = math.floor(#r / 6)
            local j = rb.bj
            while j <= nrect and budget > 0 do
                local o = (j - 1) * 6
                local ln = BannerESP.BannerNewRect(ly.cols[r[o + 5]], layer.z + r[o + 6])
                if not ln then rb.bj = j; return end
                ln.col = ly.pcol[r[o + 5]]
                ln.base = layer.base
                if not rb.probe then rb.probe = ln.Widget end
                local p = { ln = ln, x1 = r[o + 1], y1 = r[o + 2], x2 = r[o + 3], y2 = r[o + 4] }
                ly.parts[#ly.parts + 1] = p
                BannerESP.BannerPlace(ln,
                    X + p.x1 * cellX, Y + p.y1 * cellY,
                    X + p.x2 * cellX, Y + p.y2 * cellY, ppu)
                j = j + 1; budget = budget - 1
            end
            rb.bj = j
            if j > nrect then rb.bi = rb.bi + 1; rb.bj = 1 end
        end
    end

    function BannerESP.UpdateBanner(cx, show)
        local rb = BannerESP.Banner
        if show == false then
            if rb then BannerESP.BannerHide() end
            return
        end
        if not rb or not BannerESP.BannerOk(rb) then
            if rb then BannerESP.BannerDestroy() end
            rb = BannerESP.BannerCreate()
            if not rb then return end
        end
        local cellX = BannerESP.BNCellX()
        local cellY = BannerESP.BNCell()
        local ppu  = BannerESP.GetPPU()
        local cfg  = _G.LexusConfig or {}
        local offX = tonumber(cfg.CounterX) or 0
        local offY = tonumber(cfg.CounterY) or 0
        cx = math.floor(cx * ppu + 0.5) / ppu
        local Y = math.floor(((BannerESP.BN_TOPY or 47) + offY) * ppu + 0.5) / ppu

        -- ── Preferred: single downloaded texture (lag-free) ──
        if BannerESP.BN_IMG and BannerESP.BN_IMG.enabled then
            BannerESP.EnsureImage()
            local cfgImg = BannerESP.BN_IMG or {}
            local mul    = tonumber(cfgImg.sizeMul) or 1.0
            local wCanvas = (BannerESP.BN_W_DP or 640) * cellX * mul
            local X = math.floor((cx + offX - wCanvas * 0.5) * ppu + 0.5) / ppu
            if not rb.Img then BannerESP.ImageCreate(rb) end
            if BannerESP.ImageApply(rb, X, Y, cellX, cellY, ppu) then
                rb.hidden = false
                -- if a fallback border build had started, keep it hidden
                if rb.Layers then
                    for _, ly in pairs(rb.Layers) do
                        if ly.parts then
                            for _, p in ipairs(ly.parts) do
                                local w = p.ln and p.ln.Widget
                                if w and BNValid(w) and p.ln.hidden ~= true then
                                    pcall(function() w:SetWidgetVisibility(BN_HID) end)
                                    p.ln.hidden = true
                                end
                            end
                        end
                    end
                end
                return
            end
        end

        -- ── Fallback: legacy layered-rect artwork ──
        local X = math.floor((cx + offX - BannerESP.BN_W_DP * cellX * 0.5) * ppu + 0.5) / ppu
        if not rb.ready then
            BannerESP.BannerBuild(rb, X, Y, cellX, cellY, ppu)
            if not rb.ready then return end
        end
        rb.hidden = false
        for _, name in ipairs(BannerESP.BN_LAYER_ORDER) do
            BannerESP.BannerShowLayer(rb.Layers[name], X, Y, cellX, cellY, ppu)
        end
        BannerESP.BannerApplyOpacity(rb)
    end

    -- Current frame: canvas-local centre X, banner origin (X,Y), and cell.
    function BannerESP.ComputeFrame()
        local PC = PlayerMapMarker.GetMyPlayerController()
        if not PC or not slua.isValid(PC) then return nil end
        PlayerMapMarker.UpdateCanvasTransform(PC)
        local cx = PlayerMapMarker.GetSnapLineStartPos(PC)   -- canvas-local X of screen centre
        if not cx then return nil end
        local cellX = BannerESP.BNCellX()
        local cellY = BannerESP.BNCell()
        local cfg  = _G.LexusConfig or {}
        local offX = tonumber(cfg.CounterX) or 0
        local offY = tonumber(cfg.CounterY) or 0
        local X = cx + offX - BannerESP.BN_W_DP * cellX * 0.5
        local Y = (BannerESP.BN_TOPY or 47) + offY
        -- When the texture path is live, report the actual ribbon rect so
        -- labels are positioned inside the real artwork. rect = {x,y,w,h}.
        local rb = BannerESP.Banner
        if rb and rb.ImgRect then
            return cx, X, Y, cellX, cellY, rb.ImgRect
        end
        return cx, X, Y, cellX, cellY
    end
    -- Kick off texture download at module load time (so it's ready by first frame).
    pcall(function() BannerESP.EnsureImage() end)
end
_G.BannerESP = BannerESP


-- ========================================================================
-- RedBoxOverlay — same public API, banner visuals underneath.
--   REAL count → left blue panel  (x≈190 data units)
--   BOT  count → right red panel  (x≈492 data units)
-- ========================================================================
local RedBoxOverlay = {
    -- public state (read by PlayerMapMarker.ScanAndUpdate)
    bActive       = false,
    PlayerCount   = 0,
    BotCount      = 0,

    -- banner backing
    _BannerRef    = nil,
    _bBannerReady = false,

    -- labels
    RealText      = nil,
    BotText       = nil,
    _RealSlot     = nil,
    _BotSlot      = nil,

    -- legacy fields kept so no other code that pokes at them breaks
    MainContainer = nil,
    WidgetSlot    = nil,
    TextBlock     = nil,
    RealLabel     = nil,
    BotLabel      = nil,
    Width         = 300,
    Height        = 56,
    OffsetY       = 46,
    Layers        = {},
    FontSize      = 14,
    LabelFontSize = 12,
    TextScaleValue= 1.0,
    _CachedText   = "",
    _CachedPosVec = nil,
}

-- Label anchor centres in DATA units (from the capsule geometry):
--   left  blue panel ≈ x 105..299 → centre (190, 46)
--   right red  panel ≈ x 419..565 → centre (492, 46)
local BN_RED_WING_CX   = 190    -- REAL count: centred in the left blue panel
local BN_GREEN_WING_CX = 492    -- BOT  count: centred in the right red panel
local BN_WING_CY       = 46

function RedBoxOverlay._MakeText(canvas)
    local FVector2D    = _G.FVector2D or import("Vector2D")
    local FLinearColor = _G.FLinearColor or import("LinearColor")
    local FSlateColor  = import("SlateColor") or import("/Script/SlateCore.SlateColor")

    local white     = FLinearColor and FLinearColor(1, 1, 1, 1) or { R = 1, G = 1, B = 1, A = 1 }
    local fontSize  = math.max(6, math.floor((BannerESP.BN_FONT or 14) * BannerESP.GetCounterTextPct() / 100 + 0.5))

    RedBoxOverlay._makeTextFSlate = FSlateColor
    RedBoxOverlay._makeTextFont  = fontSize

    -- Keeps the label size (menu Length/Width + per-label TEXT size) and alpha
    -- (counter Opacity x per-label TEXT opacity) in sync, per label.
    function RedBoxOverlay._RefreshLabelStyle()
        local FSlateColor = RedBoxOverlay._makeTextFSlate
        local pct         = BannerESP.GetCounterTextPct()
        local baseFont    = (BannerESP.BN_FONT or 14) * pct / 100
        local opArt       = BannerESP.GetCounterOpacity()
        local cfg         = _G.LexusConfig or {}
        local pairs_ = {
            { t = RedBoxOverlay.RealText, sizeKey = "TextRealSize", opKey = "TextRealOpacity" },
            { t = RedBoxOverlay.BotText,  sizeKey = "TextBotSize",  opKey = "TextBotOpacity"  },
        }
        for _, e in ipairs(pairs_) do
            local t = e.t
            if t and slua.isValid(t) then
                local fs = math.max(4, math.floor(baseFont * (tonumber(cfg[e.sizeKey]) or 100) / 100 + 0.5))
                local a  = opArt * ((tonumber(cfg[e.opKey]) or 100) / 100)
                if a < 0 then a = 0 elseif a > 1 then a = 1 end
                pcall(function()
                    if FSlateColor then t:SetColorAndOpacity(FSlateColor({ R = 1, G = 1, B = 1, A = a }))
                    else t:SetColorAndOpacity({ R = 1, G = 1, B = 1, A = a }) end
                    -- UMG needs an explicit setter; assigning t.Font alone does
                    -- not invalidate the widget, so size changes never showed.
                    local applied = false
                    if t.SetFontSize then
                        local ok = pcall(function() t:SetFontSize(fs) end)
                        if ok then applied = true end
                    end
                    if t.Font then
                        local f = t.Font
                        if f.Size ~= fs then
                            f.Size = fs
                            if t.SetFont then
                                pcall(function() t:SetFont(f) end)
                            else
                                t.Font = f
                            end
                        end
                    end
                end)
            end
        end
    end

    local function addText(initial)
        local t = nil
        pcall(function() t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", canvas) end)
        if not t or not slua.isValid(t) then return nil, nil end
        pcall(function()
            t:SetText(initial)
            local a = BannerESP.GetCounterOpacity()
            if FSlateColor then t:SetColorAndOpacity(FSlateColor({ R = 1, G = 1, B = 1, A = a }))
            else t:SetColorAndOpacity({ R = 1, G = 1, B = 1, A = a }) end
            if t.Font then
                local f = t.Font
                f.Size = fontSize
                f.TypefaceFontName = "Bold"
                if t.SetFont then pcall(function() t:SetFont(f) end) else t.Font = f end
            end
            if t.SetFontSize then pcall(function() t:SetFontSize(fontSize) end) end
            t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        end)
        local slot = nil
        pcall(function() slot = canvas:AddChildToCanvas(t) end)
        if slot then
            pcall(function()
                slot:SetAutoSize(true)
                slot:SetAlignment(FVector2D and FVector2D(0.5, 0.5) or { X = 0.5, Y = 0.5 })
                slot:SetZOrder(2000)  -- above banner (banner z tops ~1200)
            end)
        end
        return t, slot
    end

    RedBoxOverlay.RealText, RedBoxOverlay._RealSlot = addText("REAL: 0")
    RedBoxOverlay.BotText,  RedBoxOverlay._BotSlot  = addText("BOT: 0")
    RedBoxOverlay._lastLabelSig = nil
    RedBoxOverlay._lastLabelSty = nil
end

function RedBoxOverlay._PositionLabels(X, Y, cellX, cellY, rect)
    local cfg = _G.LexusConfig or {}
    local sty = table.concat({
        tostring(BannerESP.GetCounterTextPct() or 100),
        tostring(math.floor((BannerESP.GetCounterOpacity() or 1) * 1000)),
        tostring(tonumber(cfg.TextRealSize) or 100),
        tostring(tonumber(cfg.TextRealOpacity) or 100),
        tostring(tonumber(cfg.TextBotSize) or 100),
        tostring(tonumber(cfg.TextBotOpacity) or 100),
    }, "|")
    if RedBoxOverlay._lastLabelSty ~= sty then
        RedBoxOverlay._lastLabelSty = sty
        if RedBoxOverlay._RefreshLabelStyle then pcall(RedBoxOverlay._RefreshLabelStyle) end
    end
    local rxOff = tonumber(cfg.TextRealX) or 0
    local ryOff = tonumber(cfg.TextRealY) or 0
    local bxOff = tonumber(cfg.TextBotX) or 0
    local byOff = tonumber(cfg.TextBotY) or 0

    -- Panel anchor points. With the texture path, use the ribbon's actual
    -- rect + panel fractions; otherwise use the legacy DATA-unit grid.
    local realX, realY, botX, botY
    if rect and rect.w and rect.w > 0 then
        local cfgImg = BannerESP.BN_IMG or {}
        realX = rect.x + (cfgImg.realU or 0.30) * rect.w
        botX  = rect.x + (cfgImg.botU  or 0.72) * rect.w
        realY = rect.y + (cfgImg.midV  or 0.50) * rect.h
        botY  = realY
    else
        realX = X + BN_RED_WING_CX   * cellX
        botX  = X + BN_GREEN_WING_CX * cellX
        realY = Y + BN_WING_CY       * cellY
        botY  = realY
    end
    realX = realX + rxOff; realY = realY + ryOff
    botX  = botX  + bxOff; botY  = botY  + byOff

    local sig = { realX, realY, botX, botY, rxOff, ryOff, bxOff, byOff }
    local prev = RedBoxOverlay._lastLabelSig
    if prev then
        local same = true
        for i = 1, 8 do if prev[i] ~= sig[i] then same = false; break end end
        if same then return end
    end
    RedBoxOverlay._lastLabelSig = sig
    local FVector2D = _G.FVector2D or import("Vector2D")
    if RedBoxOverlay._RealSlot and slua.isValid(RedBoxOverlay._RealSlot) then
        pcall(function()
            RedBoxOverlay._RealSlot:SetPosition(FVector2D and FVector2D(realX, realY) or { X = realX, Y = realY })
        end)
    end
    if RedBoxOverlay._BotSlot and slua.isValid(RedBoxOverlay._BotSlot) then
        pcall(function()
            RedBoxOverlay._BotSlot:SetPosition(FVector2D and FVector2D(botX, botY) or { X = botX, Y = botY })
        end)
    end
end

function RedBoxOverlay.Create()
    if RedBoxOverlay._bBannerReady and BannerESP.Banner then return true end

    if not PlayerMapMarker.InitESPCanvas() then return false end
    local canvas = PlayerMapMarker.ESPCanvas
    if not canvas or not slua.isValid(canvas) then return false end

    -- Clear anything left over from a previous match / lobby transition.
    BannerESP.BannerDestroy()

    local rb = BannerESP.BannerCreate()
    if not rb then return false end
    RedBoxOverlay._BannerRef = rb

    RedBoxOverlay._MakeText(canvas)

    RedBoxOverlay._bBannerReady = true
    RedBoxOverlay.bActive       = true
    return true
end

function RedBoxOverlay.SetCounts(players, bots)
    players = tonumber(players) or 0
    bots    = tonumber(bots)    or 0
    if RedBoxOverlay.PlayerCount == players and RedBoxOverlay.BotCount == bots then return end
    RedBoxOverlay.PlayerCount = players
    RedBoxOverlay.BotCount    = bots

    if RedBoxOverlay.RealText and slua.isValid(RedBoxOverlay.RealText) then
        pcall(function() RedBoxOverlay.RealText:SetText("REAL: " .. tostring(players)) end)
    end
    if RedBoxOverlay.BotText and slua.isValid(RedBoxOverlay.BotText) then
        pcall(function() RedBoxOverlay.BotText:SetText("BOT: " .. tostring(bots)) end)
    end
end

function RedBoxOverlay.UpdatePosition()
    if not RedBoxOverlay.bActive then return end
    local cx, X, Y, cellX, cellY, rect = BannerESP.ComputeFrame()
    if not cx then return end

    -- Bump the validity tick so BannerOk() can use its throttle.
    BannerESP._now = os.clock()
    BannerESP._vep = BannerESP._vep + 1

    BannerESP.UpdateBanner(cx, true)
    RedBoxOverlay._PositionLabels(X, Y, cellX, cellY, rect)
end

function RedBoxOverlay.Start()
    if RedBoxOverlay.bActive and RedBoxOverlay._BannerRef then return end
    if RedBoxOverlay.Create() then
        RedBoxOverlay.bActive = true
    end
end

function RedBoxOverlay.Stop()
    RedBoxOverlay.bActive       = false
    RedBoxOverlay._bBannerReady = false
    RedBoxOverlay._BannerRef    = nil

    BannerESP.BannerDestroy()

    if RedBoxOverlay.RealText and slua.isValid(RedBoxOverlay.RealText) then
        pcall(function()
            RedBoxOverlay.RealText:RemoveFromParent()
            RedBoxOverlay.RealText:ConditionalBeginDestroy()
        end)
    end
    if RedBoxOverlay.BotText and slua.isValid(RedBoxOverlay.BotText) then
        pcall(function()
            RedBoxOverlay.BotText:RemoveFromParent()
            RedBoxOverlay.BotText:ConditionalBeginDestroy()
        end)
    end

    RedBoxOverlay.RealText  = nil
    RedBoxOverlay.BotText   = nil
    RedBoxOverlay._RealSlot = nil
    RedBoxOverlay._BotSlot  = nil
end

_G.RedBoxOverlay = RedBoxOverlay
