-- ============================================================
-- SNAPLINE COLOUR PALETTES (separate for REAL players and BOTS)
--   Each list is fully independent -- edit either one and only
--   that section changes. The renderer reads the selection every
--   frame, so a tap in the menu applies instantly (no rebuild).
-- ============================================================
_G.SnaplinePaletteReal = _G.SnaplinePaletteReal or {
    { name = "RED",     r = 1.00, g = 0.10, b = 0.10 },
    { name = "GREEN",   r = 0.10, g = 1.00, b = 0.20 },
    { name = "BLUE",    r = 0.15, g = 0.45, b = 1.00 },
    { name = "YELLOW",  r = 1.00, g = 0.85, b = 0.10 },
    { name = "CYAN",    r = 0.00, g = 1.00, b = 1.00 },
    { name = "MAGENTA", r = 1.00, g = 0.10, b = 1.00 },
    { name = "ORANGE",  r = 1.00, g = 0.45, b = 0.00 },
    { name = "WHITE",   r = 1.00, g = 1.00, b = 1.00 },
}

_G.SnaplinePaletteBot = _G.SnaplinePaletteBot or {
    { name = "LIME",    r = 0.55, g = 1.00, b = 0.05 },
    { name = "PURPLE",  r = 0.60, g = 0.15, b = 1.00 },
    { name = "PINK",    r = 1.00, g = 0.30, b = 0.65 },
    { name = "TEAL",    r = 0.00, g = 0.85, b = 0.70 },
    { name = "GOLD",    r = 1.00, g = 0.72, b = 0.10 },
    { name = "SKY",     r = 0.30, g = 0.75, b = 1.00 },
    { name = "CRIMSON", r = 0.90, g = 0.05, b = 0.25 },
    { name = "WHITE",   r = 1.00, g = 1.00, b = 1.00 },
}

-- cat: "bot" -> bot palette, anything else -> real-player palette
_G.GetSnaplinePalette = function(cat)
    if cat == "bot" then return _G.SnaplinePaletteBot end
    return _G.SnaplinePaletteReal
end

_G.GetSnaplineColor = function(cat, idx)
    local pal = _G.GetSnaplinePalette(cat)
    local n = pal and #pal or 0
    if n < 1 then return 0.0, 1.0, 0.0 end
    idx = tonumber(idx) or 1
    if idx < 1 then idx = 1 elseif idx > n then idx = n end
    local c = pal[idx]
    return c.r, c.g, c.b
end

-- Authoritative snapline colour for a category, returned as 0..1 floats.
-- Stored as flat 0..255 fields so it survives the config serialiser, which
-- means the user can dial in ANY colour (not just the presets). Falls back to
-- the selected preset while no custom value exists yet.
_G.SnaplineRGBKey = function(cat)
    return (cat == "bot") and "Bot" or "Real"
end

_G.GetSnaplineRGB = function(cat)
    local cfg = _G.LexusConfig or {}
    local p = _G.SnaplineRGBKey(cat)
    local r = tonumber(cfg["SnapLine" .. p .. "R"])
    local g = tonumber(cfg["SnapLine" .. p .. "G"])
    local b = tonumber(cfg["SnapLine" .. p .. "B"])
    if r and g and b then return r / 255.0, g / 255.0, b / 255.0 end
    local idxKey = (cat == "bot") and "SnapLineColorBot" or "SnapLineColorReal"
    return _G.GetSnaplineColor(cat, cfg[idxKey] or 1)
end

_G.SetSnaplineRGB = function(cat, r, g, b)
    _G.LexusConfig = _G.LexusConfig or {}
    local p = _G.SnaplineRGBKey(cat)
    local function clamp255(v) v = math.floor(tonumber(v) or 0); if v < 0 then v = 0 elseif v > 255 then v = 255 end; return v end
    _G.LexusConfig["SnapLine" .. p .. "R"] = clamp255(r)
    _G.LexusConfig["SnapLine" .. p .. "G"] = clamp255(g)
    _G.LexusConfig["SnapLine" .. p .. "B"] = clamp255(b)
    -- custom value invalidates the preset highlight
    _G.LexusConfig["SnapLineColor" .. p] = 0
end

_G.GetSnaplineChannel = function(cat, ch)
    _G.LexusConfig = _G.LexusConfig or {}
    local p = _G.SnaplineRGBKey(cat)
    local v = tonumber(_G.LexusConfig["SnapLine" .. p .. ch])
    if v then return v end
    local r, g, b = _G.GetSnaplineRGB(cat)
    if ch == "R" then v = r elseif ch == "G" then v = g else v = b end
    return math.floor((v or 0) * 255 + 0.5)
end

-- ============================================================
-- SKIN EXTRAS (ported from 1343.lua): grenade skins, movement
-- trails, pets and weather. The menu + runtime module both read
-- these tables; grenade list is refreshed live from the game's
-- GrenadeKillGunBindMap so it always matches the current build.
-- ============================================================
_G.LexusExtras = _G.LexusExtras or {}

