-- Grenade skins: filled from the Item table (throwable subtypes) at runtime.
_G.LexusGrenadeSkins = _G.LexusGrenadeSkins or {}

-- Throwables that live on the wardrobe's Parachute page / throw_object tab:
-- 612 frag, 613 smoke, 614 quake, 615 molotov.
local LEXUS_THROW_SUBTYPES = { [612] = true, [613] = true, [614] = true, [615] = true }
local LEXUS_WARDROBE_MAIN_TAB = 5
local LEXUS_WARDROBE_THROW_TAB = 22

local function LexusItemCfg(id)
    if not (CDataTable and CDataTable.GetTableData) then return nil end
    local ok, row = pcall(CDataTable.GetTableData, "Item", id)
    if ok and type(row) == "table" then return row end
    return nil
end

-- Detailed throwable scan: { id, name, sub, mainTab, tab, inWardrobe }.
-- Shared by the mod menu row and the wardrobe injector.
_G.LexusExtras.ScanThrowables = function()
    local out, seen = {}, {}
    local function add(id, row)
        local n = tonumber(id)
        if not n or n <= 0 or seen[n] then return end
        local sub = nil
        if row then sub = tonumber(row.ItemSubType or row.itemSubType) end
        if not sub then return end
        if not LEXUS_THROW_SUBTYPES[sub] then return end
        seen[n] = true
        local mainTab = row and tonumber(row.WardrobeMainTab or row.wardrobeMainTab) or nil
        local tab = row and tonumber(row.WardrobeTab or row.wardrobeTab) or nil
        local nm = row and (row.ItemName or row.itemName or row.Name) or nil
        out[#out + 1] = {
            id = n,
            sub = sub,
            mainTab = mainTab,
            tab = tab,
            name = (nm and nm ~= "" and nm) or ("SKIN #" .. tostring(n)),
            inWardrobe = (mainTab == LEXUS_WARDROBE_MAIN_TAB and tab == LEXUS_WARDROBE_THROW_TAB),
        }
    end
    pcall(function()
        local items = CDataTable.GetTable and CDataTable.GetTable("Item")
        if type(items) ~= "table" then return end
        for id, row in pairs(items) do
            if type(row) == "table" then add(id, row) end
        end
    end)
    -- FX-bound grenade ids are usable even when the Item scan was filtered out.
    pcall(function()
        local map = CDataTable.GetTable and CDataTable.GetTable("GrenadeKillGunBindMap")
        if type(map) ~= "table" then return end
        for id in pairs(map) do add(id, LexusItemCfg(id)) end
    end)
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end

_G.LexusExtras.RefreshGrenades = function()
    pcall(function()
        local scan = _G.LexusExtras.ScanThrowables
        if type(scan) ~= "function" then return end
        local detailed = scan()
        if #detailed == 0 then return end
        local list = {}
        for i = 1, #detailed do
            list[i] = { id = detailed[i].id, name = detailed[i].name }
        end
        _G.LexusGrenadeSkins = list
    end)
end

-- Profile avatar (head icon) + avatar frame (box) choosers. Built live from
-- the game's data tables when available, otherwise from a preset list; both
-- records are strictly visual (client-side profile card).
_G.LexusAvatars = _G.LexusAvatars or {}
_G.LexusFrames  = _G.LexusFrames or {}

-- Avatar picker source: the game's "Headportrait" table (profile card page).
_G.LexusExtras.ScanAvatars = function()
    local out, seen = {}, {}
    pcall(function()
        if not (CDataTable and CDataTable.GetTable) then return end
        local tbl = CDataTable.GetTable("Headportrait")
        if type(tbl) ~= "table" then return end
        for key, row in pairs(tbl) do
            local n = tonumber(key)
            if not n and type(row) == "table" then n = tonumber(row.ID) end
            if n and n > 0 and not seen[n] and n ~= 10002 then
                seen[n] = true
                local nm = type(row) == "table" and (row.Name or row.name) or nil
                out[#out + 1] = { id = n, name = (nm and nm ~= "" and nm) or ("#" .. tostring(n)) }
            end
        end
    end)
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end

-- Avatar-frame picker source: the game's "AvatarFrame" table.
_G.LexusExtras.ScanFrames = function()
    local out, seen = {}, {}
    pcall(function()
        if not (CDataTable and CDataTable.GetTable) then return end
        local tbl = CDataTable.GetTable("AvatarFrame")
        if type(tbl) ~= "table" then return end
        for key, row in pairs(tbl) do
            local n = tonumber(key)
            if not n and type(row) == "table" then n = tonumber(row.ID) end
            if n and n > 0 and not seen[n] then
                seen[n] = true
                local nm = type(row) == "table" and (row.Name or row.name) or nil
                out[#out + 1] = { id = n, name = (nm and nm ~= "" and nm) or ("#" .. tostring(n)) }
            end
        end
    end)
    table.sort(out, function(a, b) return a.id < b.id end)
    return out
end

_G.LexusExtras.RefreshProfileItems = function()
    if #_G.LexusAvatars == 0 then
        local l = {}
        pcall(function() l = _G.LexusExtras.ScanAvatars() end)
        if #l == 0 then
            l = { { id = 30396 }, { id = 30395 }, { id = 30394 }, { id = 30393 }, { id = 30392 },
                  { id = 1001001 }, { id = 1002001 } }
            for i = 1, #l do l[i].name = "#" .. tostring(l[i].id) end
        end
        _G.LexusAvatars = l
    end
    if #_G.LexusFrames == 0 then
        local l = {}
        pcall(function() l = _G.LexusExtras.ScanFrames() end)
        if #l == 0 then
            l = { { id = 2002901 }, { id = 2002900 }, { id = 2002899 }, { id = 2002898 },
                  { id = 2002860 }, { id = 2002850 } }
            for i = 1, #l do l[i].name = "#" .. tostring(l[i].id) end
        end
        _G.LexusFrames = l
    end
end

