-- Layout metrics
local M_W = 540
local M_H = 680
local ROW_H = 38
local HEADER_H = 88
local GROUP_GAP = 12
local SUB_BAR_H = 32

-- ===== SPACING GRID =====
-- Every offset in the menu is a multiple of 4 and derives from these, so
-- padding, gutters and control sizes stay identical across the whole UI.
local PAD_X      = 16   -- panel edge -> content edge
local INSET_X    = 16   -- content edge -> row inner content
local GAP_XS     = 4
local GAP_S      = 8
local GAP_M      = 12
local ROW_MIN    = 26   -- smallest a content row may shrink to (was 32)
local ROW_R      = 6    -- rounded card-row corner radius
local CTRL_W     = 48   -- capsule switch width
