-- SETTINGS PERSISTENCE (ported from 3.lua: SaveModSettings / LoadModSettings)
-- Persists menu toggles (VIPConfig) + skin config (LexusConfig) to disk and
-- reloads them on every launch, so hacks/skins survive restarts & transitions.
-- ==============================================================================
do
    local function GetSettingsPaths(fileName)
        local paths = {
            "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName,
            "/com.tencent.ig/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/com.vng.pubgmobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/com.pubg.krmobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/com.rekoo.pubgm/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "/com.pubg.imobile/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../../ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../../../ShadowTrackerExtra/Saved/Paks/" .. fileName,
            "../../../../ShadowTrackerExtra/Saved/Paks/" .. fileName,
            fileName,
        }
        pcall(function()
            if os and os.getenv then
                local homeDir = os.getenv("HOME")
                if homeDir and homeDir ~= "" then
                    table.insert(paths, 1, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/" .. fileName)
                    table.insert(paths, 2, homeDir .. "/Documents/ShadowTrackerExtra/Saved/Paks/puffer_temp/" .. fileName)
                end
            end
        end)
        return paths
    end

    local SETTINGS_FILE = "hackv2.txt"
    _G._ShadowLastSaveStr = ""

    local function serTable(tbl)
        local s = "{\n"
        for k, v in pairs(tbl or {}) do
            local tv = type(v)
            if tv == "boolean" or tv == "number" then
                s = s .. "    [\"" .. tostring(k) .. "\"] = " .. tostring(v) .. ",\n"
            elseif tv == "string" then
                s = s .. "    [\"" .. tostring(k) .. "\"] = " .. string.format("%q", v) .. ",\n"
            end
        end
        return s .. "  }"
    end

    _G.SaveModSettings = function()
        pcall(function()
            local data = "return {\n  VIPConfig = " .. serTable(_G.VIPConfig)
                .. ",\n  LexusConfig = " .. serTable(_G.LexusConfig)
                .. ",\n  CustomTextData = " .. serTable(_G.LexusState and _G.LexusState.CustomTextData)
                .. ",\n  MenuLocked = false\n}\n"
            if data == _G._ShadowLastSaveStr then return end
            _G._ShadowLastSaveStr = data
            for _, path in ipairs(GetSettingsPaths(SETTINGS_FILE)) do
                local file = io.open(path, "w")
                if file then
                    file:write(data)
                    file:close()
                    break
                end
            end
        end)
    end

    _G.LoadModSettings = function()
        pcall(function()
            local content = nil
            for _, path in ipairs(GetSettingsPaths(SETTINGS_FILE)) do
                local file = io.open(path, "r")
                if file then
                    content = file:read("*a")
                    file:close()
                    break
                end
            end
            if not content then return end
            local func = load(content)
            if not func then return end
            local saved = func()
            if type(saved) ~= "table" then return end
            -- Menu lock: once the button has been hidden (after the 1st match),
            -- keep it hidden across game kills/restarts. Features (VIPConfig)
            -- are restored below and keep running without the menu.
            -- MenuLocked intentionally NOT restored: menu is always visible now.
            -- _G.__ShadowMenuLocked = false (default)
            if saved.VIPConfig then
                for k, v in pairs(saved.VIPConfig) do _G.VIPConfig[k] = v end
            end
            if saved.LexusConfig then
                for k, v in pairs(saved.LexusConfig) do _G.LexusConfig[k] = v end
            end
            if saved.CustomTextData then
                _G.LexusState = _G.LexusState or {}
                _G.LexusState.CustomTextData = _G.LexusState.CustomTextData or {}
                for k, v in pairs(saved.CustomTextData) do _G.LexusState.CustomTextData[k] = v end
            end
            -- Push restored states into the live _G.Mod_* hack flags.
            for cfgKey, _ in pairs(FeatureMap) do
                pcall(function() SyncFeature(cfgKey, _G.VIPConfig[cfgKey]) end)
            end
        end)
    end

    _G.ReadLiveConfig = function()
        pcall(function() if _G.SaveModSettings then _G.SaveModSettings() end end)
    end

    if not _G._ShadowConfigLoaded then
        _G.LoadModSettings()
        _G._ShadowConfigLoaded = true
    end

    pcall(function()
        local tk = require("common.time_ticker")
        if tk and tk.AddTimerLoop then
            tk.AddTimerLoop(3.0, function()
                pcall(function() if _G.SaveModSettings then _G.SaveModSettings() end end)
            end, -1, 3.0)
        end
    end)
end

local parentCanvas = nil
local menuCanvas = nil
local floatCanvas = nil
local bgPanel = nil
local allWidgets = {}
local toggleRows = {}
local floatItem = nil
local isMenuOpen = false
local menuBuilt = false
local activeTab = 1
local RefreshBadges = nil   -- assigned in BuildMenu; refreshes sidebar count badges

-- ===== FLOAT MENU BUTTON VISIBILITY =====
-- The floating MENU button is visible ONLY during the 1st match. It is hidden
-- in the lobby (before and after) and from match 2 onward. Whenever hidden it
-- is collapsed on every (re)build. The toggled features (VIPConfig) are never
-- touched, so anything enabled while the menu was on keeps running.
-- Default is hidden (lobby); shown only while the 1st match is active.
if _G.__ShadowMenuBtnHidden == nil then _G.__ShadowMenuBtnHidden = true end

local function ApplyFloatVisibility()
    if not floatItem then return end
    local show = not _G.__ShadowMenuBtnHidden
    local vis = show and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed
    local btnVis = show and UEnums.ESlateVisibility.Visible or UEnums.ESlateVisibility.Collapsed
    local layers = { floatItem.s0, floatItem.s1, floatItem.s2, floatItem.s3, floatItem.s4, floatItem.s5, floatItem.s6, floatItem.sDot, floatItem.text }
    for _, w in ipairs(layers) do
        if w then pcall(function() w:SetWidgetVisibility(vis) end) end
    end
    if floatItem.btn then
        pcall(function() floatItem.btn:SetWidgetVisibility(btnVis) end)
    end
end

local function GetCanvas()
    if parentCanvas and Game:IsValid(parentCanvas) then return parentCanvas end
    parentCanvas = nil
    pcall(function()
        local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        local MainUI = InGameUITools.GetMainControlBaseUI()
        if not MainUI or not Game:IsValid(MainUI) then return end
        if MainUI.CanvasPanel_0 and Game:IsValid(MainUI.CanvasPanel_0) then parentCanvas = MainUI.CanvasPanel_0
        elseif MainUI.CanvasPanel_42 and Game:IsValid(MainUI.CanvasPanel_42) then parentCanvas = MainUI.CanvasPanel_42 end
    end)
    return parentCanvas
end

local function MakeBtn(parent, x, y, w, h, z, onClick)
    local btn = nil
    pcall(function()
        btn = CGame:NewObjectFromPath("/Script/UMG.Button", parent)
        if btn and slua.isValid(btn) then
            pcall(function() btn:SetColorAndOpacity(C.transparent) end)
            pcall(function() btn:SetBackgroundColor(C.transparent) end)
            pcall(function() btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
            local slot = parent:AddChildToCanvas(btn)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 900)
            end
            if onClick then
                pcall(function() if btn.OnClicked then btn.OnClicked:Add(function() pcall(onClick) end) end end)
                pcall(function() if btn.OnPressed then btn.OnPressed:Add(function() pcall(onClick) end) end end)
                pcall(function() if btn.OnReleased then btn.OnReleased:Add(function() pcall(onClick) end) end end)
            end
        end
    end)
    table.insert(allWidgets, btn)
    return btn
end

local function Layer(parent, x, y, w, h, color, z)
    local b = nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(b)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 0)
            end
        end
    end)
    table.insert(allWidgets, b)
    return b
end

local function FloatLayer(parent, x, y, w, h, color, z)
    local b = nil
    pcall(function()
        b = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if b and slua.isValid(b) then
            b:SetBrushColor(color)
            b:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(b)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(x, y))
                slot:SetSize(FVector2D(w, h))
                slot:SetZOrder(z or 0)
            end
        end
    end)
