end

local function Text(parent, txt, x, y, size, color, z, alignX, alignY, bold)
    local t = nil
    pcall(function()
        t = CGame:NewObjectFromPath("/Script/UMG.TextBlock", parent)
        if t and slua.isValid(t) then
            t:SetText(txt)
            if FSlateColor then t:SetColorAndOpacity(FSlateColor(color))
            else t:SetColorAndOpacity(color) end
            if t.Font then
                local f = t.Font
                f.Size = size
                if bold then f.TypefaceFontName = "Bold" end
                t.Font = f
            end
            t:SetRenderTransformPivot(FVector2D(alignX or 0.5, alignY or 0.5))
            t:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(t)
            if slot then
                slot:SetAutoSize(true)
                slot:SetAlignment(FVector2D(alignX or 0.5, alignY or 0.5))
                slot:SetPosition(FVector2D(x, y))
                slot:SetZOrder(z or 100)
            end
        end
    end)
    table.insert(allWidgets, t)
    return t
end

-- ===== ROUNDED CORNERS =====
-- The runtime exposes no corner-radius brush, so a rounded silhouette is
-- assembled from rectangles: one central column, two side strips and a
-- staircase per corner. `quad` selects which corners to stamp; step
-- controls how finely the quarter circle is approximated.
local function RoundCorners(parent, x, y, w, h, r, quad, color, z, step)
    step = step or 1
    r = math.floor(r)
    if r < 1 then return end
    local rows = math.floor((r + step - 1) / step)
    for i = 0, rows - 1 do
        local off = i * step
        local dy = r - off
        if dy < 0 then dy = 0 end
        local inset = r - math.sqrt(math.max(0, r * r - dy * dy))
        local segW = r - inset
        local bandH = math.min(step, r - off)
        if segW > 0 and bandH > 0 then
            if quad.tl then Layer(parent, x + inset,     y + off,               segW, bandH, color, z) end
            if quad.tr then Layer(parent, x + w - r,     y + off,               segW, bandH, color, z) end
            if quad.bl then Layer(parent, x + inset,     y + h - off - bandH,   segW, bandH, color, z) end
            if quad.br then Layer(parent, x + w - r,     y + h - off - bandH,   segW, bandH, color, z) end
        end
    end
end

local function RoundedRect(parent, x, y, w, h, r, color, z, step)
    r = math.floor(math.max(0, math.min(r or 0, math.min(w, h) * 0.5)))
    if r < 1 or w - 2 * r <= 0 or h - 2 * r <= 0 then
        return Layer(parent, x, y, w, h, color, z)
    end
    local main = Layer(parent, x + r, y, w - 2 * r, h, color, z)
    Layer(parent, x, y + r, r, h - 2 * r, color, z)
    Layer(parent, x + w - r, y + r, r, h - 2 * r, color, z)
    RoundCorners(parent, x, y, w, h, r, { tl = true, tr = true, bl = true, br = true }, color, z, step or 1)
    return main
end

-- ===== UNIFIED BUTTON CHROME =====
-- One outline + surface + top highlight for every button in the menu, so
-- the close control, the slider steppers and the master pill match exactly.
local function MakeChip(parent, x, y, w, h, z, active)
    local outline = Layer(parent, x - 1, y - 1, w + 2, h + 2, active and C.accent or C.accent_dim, z)
    local surface = Layer(parent, x, y, w, h, active and C.accent_deep or C.root, z + 1)
    local gloss = Layer(parent, x, y, w, 1, C.line_hi, z + 2)
    return outline, surface, gloss
end

local function ShowMenu()
    if bgPanel and IsValid(bgPanel) then
        pcall(function() bgPanel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
    end
end

local function HideMenu()
    if bgPanel and IsValid(bgPanel) then
        pcall(function() bgPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end
end

-- ===== MENU BUTTON POLICY (visible only during the 1st match) =====
-- Uses the reliable in-match signal GameStatus.IsInFightingStatus() instead of
-- lobby events (which also fire during match loading and caused the button to
-- vanish ~1s in). The button shows only while fighting during the 1st match.
-- After that match it hides AND the hide is persisted (MenuLocked in fucm.txt),
-- so a game kill/refresh keeps the menu hidden while VIPConfig features are
-- restored and keep running. VIPConfig / feature timers are never touched.
local function UpdateMenuButtonPolicy()
    -- Menu always visible — no match-count locking, no training lock.
    -- Clear any stale lock that was saved from a previous build.
    _G.__ShadowMenuLocked = false
    _G.__ShadowMenuBtnHidden = false
end

-- ===== TOGGLE ROW STATE UPDATE =====
local function UpdateToggleRow(rowData)
    if not rowData then return end
    local state = GetFeatureState(rowData.key)
    _G.VIPConfig[rowData.key] = state

    if rowData.stateText and IsValid(rowData.stateText) then
        pcall(function()
            rowData.stateText:SetText(state and "ON" or "OFF")
            if FSlateColor then rowData.stateText:SetColorAndOpacity(FSlateColor(state and C.good or C.danger))
            else rowData.stateText:SetColorAndOpacity(state and C.good or C.danger) end
        end)
    end

    if rowData.knob and IsValid(rowData.knob) and rowData.knobSlot then
        pcall(function()
            local knobX = state and (rowData.toggleX + rowData.toggleW - rowData.knobSize - KNOB_PAD) or (rowData.toggleX + KNOB_PAD)
            rowData.knobSlot:SetPosition(FVector2D(knobX, rowData.toggleY + KNOB_PAD))
        end)
    end

    if rowData.track and IsValid(rowData.track) then
        pcall(function() rowData.track:SetBrushColor(state and C.on or C.off_dim) end)
    end

    if rowData.trackBorder and IsValid(rowData.trackBorder) then
        pcall(function() rowData.trackBorder:SetBrushColor(state and C.on or C.line) end)
    end

    if rowData.knob and IsValid(rowData.knob) then
        pcall(function() rowData.knob:SetBrushColor(state and C.white or C.off) end)
    end

    if rowData.toggleGlow and IsValid(rowData.toggleGlow) then
        pcall(function()
            rowData.toggleGlow:SetWidgetVisibility(state and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        end)
    end

    if rowData.rowGlow and IsValid(rowData.rowGlow) then
        pcall(function()
            rowData.rowGlow:SetWidgetVisibility(state and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        end)
    end

    if rowData.accent2 and IsValid(rowData.accent2) then
        pcall(function() rowData.accent2:SetBrushColor(state and C.accent or C.line) end)
    end

    if rowData.accentBar and IsValid(rowData.accentBar) then
        pcall(function()
            rowData.accentBar:SetWidgetVisibility(state and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
        end)
    end

    if rowData.label and IsValid(rowData.label) then
        pcall(function()
            if FSlateColor then rowData.label:SetColorAndOpacity(FSlateColor(state and C.text_hi or C.text))
            else rowData.label:SetColorAndOpacity(state and C.text_hi or C.text) end
        end)
    end

    if RefreshBadges then pcall(RefreshBadges) end
end

-- ===== CLEAN TOGGLE ROW (list style + capsule switch) =====
local function MakeToggleRow(parent, label, x, y, w, h, toggleKey, isZebra, noCard)
    local state = GetFeatureState(toggleKey)
    _G.VIPConfig[toggleKey] = state
    local rowData = {
        key = toggleKey,
        toggleX = x + w - INSET_X - CTRL_W,
        toggleW = CTRL_W,
        toggleH = CTRL_H,
        knobSize = KNOB_S,
    }
    rowData.toggleY = y + h * 0.5 - CTRL_H * 0.5

    -- Soft accent glow behind the row when ON (sits above any grouped card)
    rowData.rowGlow = Layer(parent, x, y, w, h, C.accent_glow, 201)
    if not state then
        pcall(function() rowData.rowGlow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end

    -- Row card surface (skipped when the row lives inside a grouped card)
    if not noCard then
        rowData.bg = RoundedRect(parent, x, y, w, h, ROW_R, isZebra and C.row_alt or C.row, 200, 2)
    end

    -- Left accent bar (visible only while the feature is ON)
    rowData.accentBar = Layer(parent, x, y + math.floor(h * 0.18), 3, math.max(4, h - math.floor(h * 0.36)), C.accent, 204)
    if not state then
        pcall(function() rowData.accentBar:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end

    -- Label
    rowData.label = Text(parent, label, x + INSET_X, y + h * 0.5, 14, state and C.text_hi or C.text, 300, 0, 0.5)

    -- ON / OFF status (right-aligned, one gutter left of the switch)
    rowData.stateText = Text(parent, state and "ON" or "OFF", rowData.toggleX - GAP_M, y + h * 0.5, 12, state and C.good or C.danger, 300, 1, 0.5)

    -- Glow behind the switch when ON
    rowData.toggleGlow = Layer(parent, rowData.toggleX - GAP_XS, rowData.toggleY - GAP_XS, rowData.toggleW + GAP_XS * 2, rowData.toggleH + GAP_XS * 2, C.accent_glow2, 298)
    if not state then
        pcall(function() rowData.toggleGlow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
    end

    -- Capsule switch (border + track)
    rowData.trackBorder = Layer(parent, rowData.toggleX - 1, rowData.toggleY - 1, rowData.toggleW + 2, rowData.toggleH + 2, state and C.on or C.line, 299)
    rowData.track = Layer(parent, rowData.toggleX, rowData.toggleY, rowData.toggleW, rowData.toggleH, state and C.on or C.off_dim, 300)
    rowData.trackInner = Layer(parent, rowData.toggleX + 1, rowData.toggleY + 1, rowData.toggleW - 2, rowData.toggleH - 2, FLinearColor(0, 0, 0, 0.18), 301)

    -- Knob
    local knobX = state and (rowData.toggleX + rowData.toggleW - rowData.knobSize - KNOB_PAD) or (rowData.toggleX + KNOB_PAD)
    local knobY = rowData.toggleY + KNOB_PAD
    rowData.knobShadow = Layer(parent, knobX, knobY + 1, rowData.knobSize, rowData.knobSize, FLinearColor(0, 0, 0, 0.35), 302)
    rowData.knobSlot = nil
    pcall(function()
        local k = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if k and slua.isValid(k) then
            k:SetBrushColor(state and C.white or C.off)
            k:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            local slot = parent:AddChildToCanvas(k)
            if slot then
                slot:SetAutoSize(false)
                slot:SetPosition(FVector2D(knobX, knobY))
                slot:SetSize(FVector2D(rowData.knobSize, rowData.knobSize))
                slot:SetZOrder(303)
            end
            rowData.knob = k
            rowData.knobSlot = slot
        end
    end)

    -- Click handler (whole row toggles)
    rowData.btn = MakeBtn(parent, x, y, w, h, 900, function()
        _G.VIPConfig[toggleKey] = not _G.VIPConfig[toggleKey]
        SyncFeature(toggleKey, _G.VIPConfig[toggleKey])
        UpdateToggleRow(rowData)
    end)

    table.insert(toggleRows, rowData)
    return rowData
end

-- ===== SLIDER ROW (for fine-tune values) =====
local function MakeSliderRow(parent, opt, x, y, w, h, isZebra, noCard)
    local label = opt.label
    local getText = opt.getText
    local onClick = opt.onClick
    local rowData = { key = label, isSlider = true }

    -- Row card surface (skipped when the row lives inside a grouped card)
    if not noCard then
        rowData.bg = RoundedRect(parent, x, y, w, h, ROW_R, isZebra and C.row_alt or C.row, 200, 2)
    end
    rowData.label = Text(parent, label, x + INSET_X, y + h * 0.5, 14, C.text, 300, 0, 0.5)

    -- Step buttons share one chrome with every other button in the menu
    local btnW = BTN_S
    local btnH = BTN_S
    local btnY = y + h * 0.5 - btnH * 0.5
    local plusX = x + w - INSET_X - btnW
    local minusX = plusX - btnW - GAP_S
    local valRight = minusX - GAP_M

    -- Current value (right-aligned before the buttons)
    local valText = getText()
    rowData.valText = Text(parent, valText, valRight, y + h * 0.5, 13, C.text_hi, 300, 1, 0.5)

    -- Value track (fill %)
    local trackX = x + INSET_X
    local trackW = minusX - GAP_S - trackX
    if trackW < 20 then trackW = 20 end
    local trackY = y + h - 7
    Layer(parent, trackX, trackY, trackW, 3, C.line_hi, 204)

    local function computeFrac()
        if opt.min and opt.max and opt.getValue then
            local v = opt.getValue()
            if type(v) ~= "number" then return 0 end
            local fr = (v - opt.min) / math.max(1, (opt.max - opt.min))
            if fr < 0 then fr = 0 end
            if fr > 1 then fr = 1 end
            return fr
        end
        return 0
    end

    local fillSlot = nil
    local fillWidget = nil
    pcall(function()
        local fill = CGame:NewObjectFromPath("/Script/UMG.Border", parent)
        if fill and slua.isValid(fill) then
            fill:SetBrushColor(opt.getColor and opt.getColor() or C.accent)
            if UEnums and UEnums.ESlateVisibility then
                fill:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            end
            fillSlot = parent:AddChildToCanvas(fill)
            if fillSlot then
                fillSlot:SetAutoSize(false)
                fillSlot:SetPosition(FVector2D(trackX, trackY))
                fillSlot:SetSize(FVector2D(trackW * computeFrac(), 3))
                fillSlot:SetZOrder(205)
            end
            fillWidget = fill
        end
    end)

    local function updateFill()
        if fillSlot then
            pcall(function()
                fillSlot:SetSize(FVector2D(trackW * computeFrac(), 3))
                if opt.getColor and fillWidget and slua.isValid(fillWidget) then
                    fillWidget:SetBrushColor(opt.getColor())
                end
            end)
        end
    end

    local function makeStepBtn(bx, sym, col, cb)
        MakeChip(parent, bx, btnY, btnW, btnH, 298, false)
        Text(parent, sym, bx + btnW * 0.5, btnY + btnH * 0.5, 15, col, 400, 0.5, 0.5, true)
        MakeBtn(parent, bx, btnY, btnW, btnH, 900, cb)
    end

    makeStepBtn(minusX, "-", C.text, function()
        onClick(-1)
        if rowData.valText and IsValid(rowData.valText) then
            pcall(function() rowData.valText:SetText(getText()) end)
        end
        updateFill()
    end)

    makeStepBtn(plusX, "+", C.accent_hi, function()
        onClick(1)
        if rowData.valText and IsValid(rowData.valText) then
            pcall(function() rowData.valText:SetText(getText()) end)
        end
        updateFill()
    end)

    table.insert(toggleRows, rowData)
    return rowData
end

-- ===== COLOUR SWATCH ROW =====
-- Tap any swatch to select it. `opt.cfgKey` is the LexusConfig index written on
-- tap; `opt.default` is the fallback. Reads live so the highlighted swatch and
-- the in-game colour always match, with zero rebuild.
local function MakeColorRow(parent, opt, x, y, w, h, isZebra, noCard)
    local pal = (_G.GetSnaplinePalette and _G.GetSnaplinePalette(opt.cat)) or opt.palette or {}
    local n = #pal
    local cfgKey = opt.cfgKey
    local rowData = { isColor = true, key = opt.label }

    -- A preset is "selected" when the live colour matches it (so a hand-dialled
    -- custom colour simply highlights nothing).
    local function matchSel()
        local cr, cg, cb = _G.GetSnaplineRGB(opt.cat)
        for i = 1, n do
            local c = pal[i]
            if c and math.abs(c.r - cr) < 0.02 and math.abs(c.g - cg) < 0.02 and math.abs(c.b - cb) < 0.02 then
                return i
            end
        end
        return 0
    end

    if not noCard then
        RoundedRect(parent, x, y, w, h, ROW_R, C.card, 200, 1)
    end

    Text(parent, opt.label or "COLOR", x + INSET_X, y + h * 0.5, 11, C.text, 300, 0, 0.5, true)

    local labelW = 60
    local leftX = x + INSET_X + labelW
    local rightX = x + w - INSET_X
    if n > 0 and (rightX - leftX) < (n * 12) then
        leftX = x + INSET_X
    end
    local availW = rightX - leftX
    local gap = 5
    local sw = math.floor((availW - gap * (n - 1)) / n)
    if sw < 8 then sw = 8 end
    local sh = math.floor(math.min(h - 16, sw + 2))
    if sh > 26 then sh = 26 end
    if sh < 8 then sh = 8 end
    local sy = y + (h - sh) * 0.5

    local rings, ticks = {}, {}
    local function refresh()
        local sel = matchSel()
        for i = 1, n do
            local ring = rings[i]
            if ring and slua.isValid(ring) then
                pcall(function() ring:SetBrushColor(i == sel and C.accent_hi or C.line) end)
            end
            local tick = ticks[i]
            if tick and slua.isValid(tick) then
                local vis = (i == sel) and UEnums.ESlateVisibility.SelfHitTestInvisible
                                          or UEnums.ESlateVisibility.Collapsed
                pcall(function() tick:SetWidgetVisibility(vis) end)
            end
        end
    end

    for i = 1, n do
        local c = pal[i] or { r = 1.0, g = 1.0, b = 1.0 }
        local sx = leftX + (i - 1) * (sw + gap)
        if (sx + sw) > rightX then sx = rightX - sw end
        rings[i] = Layer(parent, sx - 2, sy - 2, sw + 4, sh + 4,
                         (i == matchSel()) and C.accent_hi or C.line, 208)
        Layer(parent, sx, sy, sw, sh, FLinearColor(c.r, c.g, c.b, 1.0), 210)
        ticks[i] = Layer(parent, sx + sw * 0.5 - 2, sy + sh * 0.5 - 2, 4, 4, C.white, 212)
        MakeBtn(parent, sx, sy, sw, sh, 901, function()
            _G.SetSnaplineRGB(opt.cat, c.r * 255, c.g * 255, c.b * 255)
            refresh()
        end)
    end

    refresh()

    table.insert(toggleRows, rowData)
    return rowData
end

-- ===== GROUPED CARD RENDERER =====
-- One rounded card per group of rows; rows sit flush inside, separated by
-- hairline dividers. Returns the total height consumed by the group.
local function RenderGroup(parent, opts, x, y, w, rowH, withCard)
    local n = #opts
    if n == 0 then return 0 end
    local groupH = n * rowH
    if withCard ~= false then
        RoundedRect(parent, x, y, w, groupH, ROW_R, C.card, 200, 2)
    end
    for i, opt in ipairs(opts) do
        local ry = y + (i - 1) * rowH
        if i > 1 then
            Layer(parent, x + INSET_X, ry, w - INSET_X * 2, 1, C.line, 203)
        end
        if opt.swatch then
            MakeColorRow(parent, opt, x, ry, w, rowH, false, true)
        elseif opt.slider then
            MakeSliderRow(parent, opt, x, ry, w, rowH, false, true)
        else
            if _G.VIPConfig[opt.key] == nil then _G.VIPConfig[opt.key] = false end
            MakeToggleRow(parent, opt.label, x, ry, w, rowH, opt.key, false, true)
        end
    end
    return groupH
end

