-- ===== BUILD MENU =====
local function BuildMenu()
    if menuBuilt and bgPanel and IsValid(bgPanel) then
        ShowMenu()
        return
    end

    local canvas = GetCanvas()
    if not canvas then return end
    menuCanvas = canvas

    -- ===== FIT TO SCREEN (responsive + content-aware) =====
    -- 1) viewport in SCREEN pixels
    local vwPx, vhPx = nil, nil
    pcall(function()
        local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
        if pc and pc.GetViewportSize then
            local vs = FVector2D(0, 0)
            pc:GetViewportSize(vs)
            if vs and vs.X and vs.Y and vs.X > 320 and vs.Y > 320 then vwPx, vhPx = vs.X, vs.Y end
        end
    end)
    if not vwPx then
        pcall(function()
            local ok, ui_util = pcall(require, "client.common.ui_util")
            if ok and ui_util and ui_util.GetViewportSize then
                local vp = ui_util.GetViewportSize()
                if vp and vp.X and vp.Y and vp.X > 320 and vp.Y > 320 then vwPx, vhPx = vp.X, vp.Y end
            end
        end)
    end

    -- 2) canvas-local units per screen pixel for THIS canvas (same
    --    AbsoluteToLocal technique the ESP overlay already uses).
    local unitsX, unitsY = nil, nil
    pcall(function()
        if SlateBlueprintLibrary and SlateBlueprintLibrary.AbsoluteToLocal and canvas.GetCachedGeometry then
            local cg = canvas:GetCachedGeometry()
            if cg then
                local p0 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(0, 0))
                local p1 = SlateBlueprintLibrary.AbsoluteToLocal(cg, FVector2D(100, 100))
                if p0 and p1 then
                    local dx, dy = (p1.X - p0.X) / 100, (p1.Y - p0.Y) / 100
                    if dx > 0 and dy > 0 then unitsX, unitsY = dx, dy end
                end
            end
        end
    end)
    if not unitsX then
        pcall(function()
            local pc = slua_GameFrontendHUD and slua_GameFrontendHUD:GetPlayerController()
            if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportScale and pc then
                local s = WidgetLayoutLibrary.GetViewportScale(pc)
                if s and type(s) == "number" and s > 0 then unitsX, unitsY = 1 / s, 1 / s end
            end
        end)
    end
    if not unitsX then unitsX, unitsY = 1, 1 end

    local vw = vwPx and (vwPx * unitsX) or nil
    local vh = vhPx and (vhPx * unitsY) or nil

    -- 3) smallest content height that lets every tab fit without clipping
    local minContentH = 120
    pcall(function()
        for _, td in ipairs(tabDefs) do
            local sections = td.sections or {}
            local nGroups, nRows = #sections, 0
            for _, s in ipairs(sections) do nRows = nRows + #s.opts end
            local hasSub = td.subTabs and #td.subTabs > 0
            if hasSub then
                local mx = 0
                for _, s in ipairs(td.subTabs) do if #s.opts > mx then mx = #s.opts end end
                nRows = nRows + mx
                nGroups = nGroups + 1
            end
            local fixedH = 8 + math.max(0, nGroups - 1) * GROUP_GAP
            if hasSub then fixedH = fixedH + SUB_BAR_H + GROUP_GAP end
            local need = fixedH + nRows * ROW_MIN + 8
            if need > minContentH then minContentH = need end
        end
    end)
    -- Panel must fit the taller of: the content column, or the sidebar rows
    -- (so the last tab row can never overrun into the footer).
    local sidebarNeed = #tabDefs * (ROW_SIDE_H + GAP_XS) + GAP_S
    local minPanelH = HEADER_H + FOOTER_H + math.max(sidebarNeed, GAP_S + minContentH)

    -- 4) target proportions: ~74% x ~58% of the viewport, never exceeding it
    if vw and vw > 320 then
        M_W = math.floor(vw * 0.74)
        if M_W > vw - 48 then M_W = math.floor(vw - 48) end
    else
        M_W = 540
    end
    if M_W < 320 then M_W = 320 end
    if M_W > M_W_MAX then M_W = M_W_MAX end

    if vh and vh > 300 then
        M_H = math.floor(vh * 0.66)
        if M_H < minPanelH then M_H = minPanelH end
        if M_H > vh - 40 then M_H = math.floor(vh - 40) end
    else
        M_H = 680
    end
    if M_H < 300 then M_H = 300 end
    if M_H > M_H_MAX then M_H = M_H_MAX end

    pcall(function()
        bgPanel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        if bgPanel and slua.isValid(bgPanel) then
            local slot = canvas:AddChildToCanvas(bgPanel)
            if slot then
                slot:SetAutoSize(false)
                slot:SetZOrder(10000)
                slot:SetAnchors(FAnchors(0.5, 0.5, 0.5, 0.5))
                slot:SetAlignment(FVector2D(0.5, 0.5))
                slot:SetPosition(FVector2D(0, 0))
                slot:SetSize(FVector2D(M_W, M_H))
            end
        end
    end)
    if not bgPanel or not slua.isValid(bgPanel) then return end

    -- ===== GLASS SURFACE (single translucent Border, 5.lua style) =====
    -- One Border at alpha 0.50 so the game world reads straight through it.
    -- (The old build filled a whole opaque C.accent rect behind the glass,
    --  and stacked drop shadows over it, which is why it never looked clear.)
    Layer(bgPanel, 0, 0, M_W, M_H, C.panel, 1)

    -- ===== THIN CYAN EDGE (1px outline, 5.lua style) =====
    Layer(bgPanel, 0, 0, M_W, 1, C.accent, 6)
    Layer(bgPanel, 0, M_H - 1, M_W, 1, C.accent, 6)
    Layer(bgPanel, 0, 0, 1, M_H, C.accent, 6)
    Layer(bgPanel, M_W - 1, 0, 1, M_H, C.accent, 6)

    -- ===== HEADER (branding left | status + close right) =====
    local headerY = 0
    Layer(bgPanel, 0, headerY, M_W, HEADER_H, C.header, 2)

    -- Refined logo: three nested POINTED boxes (squares rotated 45° → diamonds,
    -- sharp corners, no rounding). Dark diamonds act as the gaps between them.
    local plateS = 34
    local plateX = PAD_X
    local plateY = headerY + math.floor((HEADER_H - plateS) * 0.5)
    local plateCX = plateX + plateS * 0.5
    local plateCY = plateY + plateS * 0.5
    local function Diamond(sz, color, z)
        local d = Layer(bgPanel, plateCX - sz * 0.5, plateCY - sz * 0.5, sz, sz, color, z)
        if d then
            pcall(function()
                d:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                d:SetRenderTransformAngle(45)
            end)
        end
        return d
    end
    Diamond(28, C.accent, 4)      -- big box
    Diamond(21, C.root, 5)        -- gap
    Diamond(15, C.accent, 6)      -- small box inside
    Diamond(9,  C.root, 7)        -- gap
    Diamond(4,  C.accent_hi, 8)   -- small box inside it

    -- Main title + subtitle (aligned to the emblem gutter)
    local brandX = plateX + plateS + GAP_M
    Text(bgPanel, "CHETAN VIP PORTAL", brandX, headerY + HEADER_H * 0.36, 19, C.text_hi, 500, 0, 0.5, true)
    Text(bgPanel, "PREMIUM ACCESS", brandX, headerY + HEADER_H * 0.60, 10, C.accent_dim, 300, 0, 0.5, true)

    -- Accent scanline rule (fading cyan segments)
    local scanY = headerY + HEADER_H * 0.60 + 11
    Layer(bgPanel, brandX, scanY, 116, 2, C.accent, 6)
    Layer(bgPanel, brandX + 116, scanY, 54, 2, C.accent_dim, 6)
    Layer(bgPanel, brandX + 170, scanY, 34, 2, FLinearColor(0, 0.8667, 0.9608, 0.30), 6)

    -- Close control (original callback preserved) — same chrome as every button
    local closeSize = BTN_S
    local closeX = M_W - closeSize - PAD_X
    local closeY = headerY + math.floor((HEADER_H - closeSize) * 0.5)
    MakeChip(bgPanel, closeX, closeY, closeSize, closeSize, 3, false)
    Text(bgPanel, "X", closeX + closeSize * 0.5, closeY + closeSize * 0.5, 14, C.text_hi, 400, 0.5, 0.5, true)
    MakeBtn(bgPanel, closeX, closeY, closeSize, closeSize, 900, function()
        isMenuOpen = false
        HideMenu()
    end)

    -- Status label (withheld on narrow panels so nothing can overlap)
    if M_W >= 470 then
        local statusW = 148
        local statusH = BTN_S
        local statusX = closeX - statusW - GAP_M
        local statusY = headerY + math.floor((HEADER_H - statusH) * 0.5)
        MakeChip(bgPanel, statusX, statusY, statusW, statusH, 3, false)
        Layer(bgPanel, statusX + GAP_S, statusY + statusH * 0.5 - 2.5, 5, 5, C.accent, 5)
        Text(bgPanel, "PREMIUM · v4.6", statusX + GAP_S + 5 + GAP_S, statusY + statusH * 0.5, 10, C.accent_hi, 300, 0, 0.5, true)
    end

    -- Header divider: hairline + bright accent segment (5.lua-style thin rule)
    Layer(bgPanel, 0, headerY + HEADER_H - 1, M_W, 1, C.line, 4)
    Layer(bgPanel, PAD_X, headerY + HEADER_H - 1, 72, 1, C.accent, 5)

    -- ===== VERTICAL SIDEBAR (replaces the horizontal top tab bar, §4.3 / Phase 3) =====
    local bodyTop = headerY + HEADER_H
    local bodyH = M_H - bodyTop - FOOTER_H
    if bodyH < 120 then bodyH = 120 end
    local SIDE_W = math.floor(M_W * SIDE_FRAC)
    if SIDE_W < 104 then SIDE_W = 104 end
    if SIDE_W > 180 then SIDE_W = 180 end

    -- Sidebar surface (slightly darker than content) + cyan seam to the content
    Layer(bgPanel, SIDE_W, bodyTop, M_W - SIDE_W, bodyH, C.surface_lo, 1)  -- content #111720
    Layer(bgPanel, 0, bodyTop, SIDE_W, bodyH, C.surface, 2)                -- sidebar #0B0E13
    Layer(bgPanel, SIDE_W, bodyTop, 1, bodyH, C.line, 3)
    Layer(bgPanel, SIDE_W + 1, bodyTop, 1, bodyH, C.accent_glow2, 3)

    local tabWidgets = {}
    local contentPanels = {}

    local function SwitchTab(tabIndex)
        activeTab = tabIndex
        for i, tw in ipairs(tabWidgets) do
            local isActive = (i == tabIndex)
            if tw.bg and IsValid(tw.bg) then tw.bg:SetBrushColor(isActive and C.surface_hi or C.transparent) end
            if tw.glow and IsValid(tw.glow) then
                tw.glow:SetWidgetVisibility(isActive and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            end
            if tw.ind and IsValid(tw.ind) then
                tw.ind:SetWidgetVisibility(isActive and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            end
            if tw.dot and IsValid(tw.dot) then
                tw.dot:SetWidgetVisibility(isActive and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            end
            if tw.txt and IsValid(tw.txt) then
                pcall(function()
                    if FSlateColor then tw.txt:SetColorAndOpacity(FSlateColor(isActive and C.accent_hi or C.text_dim))
                    else tw.txt:SetColorAndOpacity(isActive and C.accent_hi or C.text_dim) end
                end)
            end
        end
        for i, cp in ipairs(contentPanels) do
            if cp and IsValid(cp) then
                cp:SetWidgetVisibility(i == tabIndex and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
            end
        end
    end

    -- One clickable row per tab; active = brighter surface + cyan text + cyan
    -- left-edge indicator. Rows reuse SwitchTab/contentPanels (no per-tab dupes).
    local sideRowX = PAD_X
    local sideRowW = SIDE_W - PAD_X - GAP_M
    local sidebarBadges = {}
    for i, tabDef in ipairs(tabDefs) do
        local isActive = (i == 1)
        local rowY = bodyTop + GAP_S + (i - 1) * (ROW_SIDE_H + GAP_XS)
        local rowGlow = Layer(bgPanel, sideRowX, rowY, sideRowW, ROW_SIDE_H, C.accent_glow2, 11)
        local rowBg = Layer(bgPanel, sideRowX, rowY, sideRowW, ROW_SIDE_H, isActive and C.surface_hi or C.transparent, 12)
        local rowInd = Layer(bgPanel, sideRowX, rowY, GAP_XS, ROW_SIDE_H, C.accent, 13)
        if not isActive then
            pcall(function() rowGlow:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
            pcall(function() rowInd:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) end)
        end
        local rowTxt = Text(bgPanel, tabDef.name, sideRowX + GAP_XS + GAP_S, rowY + ROW_SIDE_H * 0.5, 13, isActive and C.accent_hi or C.text_dim, 400, 0, 0.5, true)
        -- Enabled-feature count badge (right-aligned inset capsule)
        local rowBadgeBg = Layer(bgPanel, sideRowX + sideRowW - GAP_S - 22, rowY + ROW_SIDE_H * 0.5 - 8, 22, 16, C.accent_deep, 13)
        local rowBadgeTxt = Text(bgPanel, "", sideRowX + sideRowW - GAP_S - 11, rowY + ROW_SIDE_H * 0.5, 10, C.accent_hi, 500, 0.5, 0.5, true)
        sidebarBadges[i] = { bg = rowBadgeBg, txt = rowBadgeTxt }
        local tabIdx = i
        MakeBtn(bgPanel, sideRowX, rowY, sideRowW, ROW_SIDE_H, 900, function()
            SwitchTab(tabIdx)
        end)
        tabWidgets[i] = { bg = rowBg, txt = rowTxt, ind = rowInd, glow = rowGlow }
    end

    -- Recompute per-tab enabled-feature counts (called on every toggle).
    RefreshBadges = function()
        for i, td in ipairs(tabDefs) do
            local b = sidebarBadges[i]
            if b then
                local cnt = 0
                local function tally(list)
                    for _, opt in ipairs(list or {}) do
                        if opt.key and _G.VIPConfig[opt.key] then cnt = cnt + 1 end
                    end
                end
                for _, s in ipairs(td.sections or {}) do tally(s.opts) end
                for _, s in ipairs(td.subTabs or {}) do tally(s.opts) end
                if b.txt and IsValid(b.txt) then pcall(function() b.txt:SetText(cnt > 0 and tostring(cnt) or "") end) end
                if b.bg and IsValid(b.bg) then
                    pcall(function()
                        b.bg:SetWidgetVisibility((cnt > 0) and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
                    end)
                end
            end
        end
    end
    RefreshBadges()

    -- ===== CONTENT AREA (right of the sidebar) =====
    local contentX = SIDE_W + PAD_X
    local contentW = M_W - SIDE_W - PAD_X * 2
    local contentTop = bodyTop + GAP_S
    local contentH = M_H - contentTop - FOOTER_H
    if contentH < 120 then contentH = 120 end
    local MIN_ROW_H = ROW_MIN

    for tabIdx, tabData in ipairs(tabDefs) do
        local hasSub = tabData.subTabs and #tabData.subTabs > 0

        -- Shrink rows so every option fits inside the (possibly clamped) panel.
        local sections = tabData.sections or {}
        local nRows, nGroups = 0, #sections
        for _, s in ipairs(sections) do nRows = nRows + #s.opts end
        if hasSub then
            local maxSubRows = 0
            for _, s in ipairs(tabData.subTabs) do maxSubRows = math.max(maxSubRows, #s.opts) end
            nRows = nRows + maxSubRows
            nGroups = nGroups + 1
        end
        local fixedH = 8 + math.max(0, nGroups - 1) * GROUP_GAP
        if hasSub then fixedH = fixedH + SUB_BAR_H + GROUP_GAP end
        local rowH = ROW_H
        if nRows > 0 then
            local fit = math.floor((contentH - fixedH) / nRows)
            if fit < rowH then rowH = fit end
            if rowH < MIN_ROW_H then rowH = MIN_ROW_H end
        end

        local panel = nil
        pcall(function()
            panel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", bgPanel)
            if panel and slua.isValid(panel) then
                local slot = bgPanel:AddChildToCanvas(panel)
                if slot then
                    slot:SetAutoSize(false)
                    slot:SetPosition(FVector2D(0, contentTop))
                    slot:SetSize(FVector2D(M_W, contentH))
                    slot:SetZOrder(10)
                end
                if tabIdx == 1 then
                    panel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                else
                    panel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                end
            end
        end)
        contentPanels[tabIdx] = panel
        if not panel or not slua.isValid(panel) then panel = bgPanel end

        local cY = 0
        -- Grouped cards: one rounded surface per section, rows flush inside
        -- (hairline separated). Section titles stay omitted for density.
        for gi, section in ipairs(sections) do
            if gi > 1 then cY = cY + GROUP_GAP end
            cY = cY + RenderGroup(panel, section.opts, contentX, cY, contentW, rowH, true)
        end

        if hasSub then
            -- ===== SEGMENTED SUB-TAB BAR (+ optional master pill) =====
            cY = cY + GROUP_GAP
            local barY = cY
            local masterW = tabData.masterKey and 150 or 0
            local subRegionW = contentW - masterW
            local subTabW = subRegionW / #tabData.subTabs

            -- Segmented track
            Layer(panel, contentX, barY, subRegionW, SUB_BAR_H, C.surface_lo, 250)
            Layer(panel, contentX, barY, subRegionW, 1, C.line, 251)

            -- Moving thumb (behind labels)
            local thumbSlot = nil
            pcall(function()
                local th = CGame:NewObjectFromPath("/Script/UMG.Border", panel)
                if th and slua.isValid(th) then
                    th:SetBrushColor(C.surface_hi)
                    if UEnums and UEnums.ESlateVisibility then
                        th:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                    end
                    thumbSlot = panel:AddChildToCanvas(th)
                    if thumbSlot then
                        thumbSlot:SetAutoSize(false)
                        thumbSlot:SetPosition(FVector2D(contentX + 2, barY + 2))
                        thumbSlot:SetSize(FVector2D(subTabW - 4, SUB_BAR_H - 4))
                        thumbSlot:SetZOrder(252)
                    end
                end
            end)

            local subTxt, subPanels = {}, {}
            local activeSub = 1

            local function RefreshSubBar()
                for i = 1, #tabData.subTabs do
                    if subTxt[i] and IsValid(subTxt[i]) then
                        pcall(function()
                            if FSlateColor then subTxt[i]:SetColorAndOpacity(FSlateColor(i == activeSub and C.accent_hi or C.text_dim))
                            else subTxt[i]:SetColorAndOpacity(i == activeSub and C.accent_hi or C.text_dim) end
                        end)
                    end
                    if subPanels[i] and IsValid(subPanels[i]) then
                        subPanels[i]:SetWidgetVisibility(i == activeSub and UEnums.ESlateVisibility.SelfHitTestInvisible or UEnums.ESlateVisibility.Collapsed)
                    end
                end
                if thumbSlot then
                    pcall(function() thumbSlot:SetPosition(FVector2D(contentX + 2 + (activeSub - 1) * subTabW, barY + 2)) end)
                end
            end

            for subIdx, sub in ipairs(tabData.subTabs) do
                local bx = contentX + (subIdx - 1) * subTabW
                subTxt[subIdx] = Text(panel, sub.title, bx + subTabW * 0.5, barY + SUB_BAR_H * 0.5, 12, subIdx == 1 and C.accent_hi or C.text_dim, 400, 0.5, 0.5, true)
                MakeBtn(panel, bx, barY, subTabW, SUB_BAR_H, 900, function()
                    activeSub = subIdx
                    RefreshSubBar()
                end)

                -- Sub content panel (stacked below the sub-tab bar)
                local subPanel = nil
                pcall(function()
                    subPanel = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", panel)
                    if subPanel and slua.isValid(subPanel) then
                        local slot = panel:AddChildToCanvas(subPanel)
                        if slot then
                            slot:SetAutoSize(false)
                            slot:SetPosition(FVector2D(0, barY + SUB_BAR_H))
                            slot:SetSize(FVector2D(M_W, math.max(1, contentH - (barY + SUB_BAR_H))))
                            slot:SetZOrder(260)
                        end
                        if subIdx == 1 then
                            subPanel:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                        else
                            subPanel:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                        end
                    end
                end)
                subPanels[subIdx] = subPanel
                if not subPanel or not slua.isValid(subPanel) then subPanel = panel end

                RenderGroup(subPanel, sub.opts, contentX, 4, contentW, rowH, true)
            end

            -- Master enable pill (right of the segmented control) — shared chrome
            if tabData.masterKey then
                local mk = tabData.masterKey
                if _G.VIPConfig[mk] == nil then _G.VIPConfig[mk] = false end
                local pillX = contentX + subRegionW + GAP_S
                local pillW = masterW - GAP_S
                local pillH = SUB_BAR_H - GAP_XS
                local pillY = barY + GAP_XS * 0.5
                local on0 = _G.VIPConfig[mk]
                local pillOutline, pillBg = MakeChip(panel, pillX, pillY, pillW, pillH, 253, on0)
                local pillTxt = Text(panel, "AIM " .. (on0 and "ON" or "OFF"), pillX + pillW * 0.5, pillY + pillH * 0.5, 12, on0 and C.accent_hi or C.text_dim, 400, 0.5, 0.5, true)
                MakeBtn(panel, pillX, pillY, pillW, pillH, 900, function()
                    local on = not (_G.VIPConfig[mk] or false)
                    _G.VIPConfig[mk] = on
                    pcall(function() SyncFeature(mk, on) end)
                    pcall(function() pillBg:SetBrushColor(on and C.accent_deep or C.surface_lo) end)
                    pcall(function() pillOutline:SetBrushColor(on and C.accent or C.accent_dim) end)
                    pcall(function()
                        if FSlateColor then pillTxt:SetColorAndOpacity(FSlateColor(on and C.accent_hi or C.text_dim))
                        else pillTxt:SetColorAndOpacity(on and C.accent_hi or C.text_dim) end
                        pillTxt:SetText("AIM " .. (on and "ON" or "OFF"))
                    end)
                end)
            end
        end
    end

    -- ===== FOOTER =====
    local fY = M_H - 34
    Layer(bgPanel, PAD_X, fY, M_W - PAD_X * 2, 1, C.line, 6)
    Layer(bgPanel, PAD_X, fY, 48, 1, C.accent, 7)
    Text(bgPanel, "CHETAN MODZ", PAD_X, fY + 17, 9, C.text_faint, 300, 0, 0.5, true)
    Text(bgPanel, "UI 2.0 · BUILD 4.6", M_W * 0.5, fY + 17, 9, C.text_dim, 300, 0.5, 0.5, true)
    Text(bgPanel, "SYSTEM ONLINE", M_W - PAD_X, fY + 17, 9, C.accent_hi, 400, 1, 0.5, true)
    Layer(bgPanel, M_W - PAD_X - 92, fY + 14.5, 5, 5, C.good, 8)

    menuBuilt = true
    isMenuOpen = true
end

-- ===== FLOAT LAUNCH BUTTON =====

local function CreateFloat()
    if floatItem and floatItem.btn and IsValid(floatItem.btn) then return end
    floatItem = nil
    pcall(function()
        local canvas = GetCanvas()
        if not canvas then return end

        floatItem = {}
        floatCanvas = canvas
        local fW = 96
        local fH = 34
        -- Anchor the button to the top-left corner of the HUD canvas.
        local host = nil
        local fX, fY = 16, 24    -- fallback: top-left placement
        pcall(function()
            local container = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
            if container and slua.isValid(container) then
                pcall(function() container:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible) end)
                local cslot = canvas:AddChildToCanvas(container)
                if cslot then
                    cslot:SetAutoSize(false)
                    cslot:SetAnchors(FAnchors(0, 0, 0, 0))
                    cslot:SetAlignment(FVector2D(0, 0))
                    cslot:SetPosition(FVector2D(12, 24))
                    cslot:SetSize(FVector2D(fW + 14, fH))
                    cslot:SetZOrder(11890)
                    host = container
                    fX, fY = 7, 0
                end
            end
        end)
        if not host then host = canvas end

        -- Elevated shadow
        floatItem.s0 = FloatLayer(host, fX - 5, fY + 5, fW + 10, fH + 5, C.shadow_l, 11895)
        floatItem.s1 = FloatLayer(host, fX - 2, fY + 2, fW + 4, fH + 2, C.shadow_m, 11896)

        -- Outer border / glass plate
        floatItem.s2 = FloatLayer(host, fX - 1, fY - 1, fW + 2, fH + 2, C.border_hi, 11899)
        floatItem.s3 = FloatLayer(host, fX, fY, fW, fH, C.header, 11902)
        floatItem.s4 = FloatLayer(host, fX, fY, fW, 2, C.accent_hi, 11903)
        floatItem.s5 = FloatLayer(host, fX, fY + fH - 2, fW, 2, C.accent_dim, 11904)

        -- Accent glass tint
        floatItem.s6 = FloatLayer(host, fX + 3, fY + 3, fW - 6, fH - 6, C.accent_glow, 11905)

        -- Status dot
        floatItem.sDot = FloatLayer(host, fX + 9, fY + fH * 0.5 - 2.5, 5, 5, C.accent, 12000)

        -- Label
        pcall(function()
            floatItem.text = CGame:NewObjectFromPath("/Script/UMG.TextBlock", host)
            if floatItem.text and slua.isValid(floatItem.text) then
                floatItem.text:SetText("CHETAN MENU")
                if FSlateColor then floatItem.text:SetColorAndOpacity(FSlateColor(C.accent_hi))
                else floatItem.text:SetColorAndOpacity(C.accent_hi) end
                if floatItem.text.Font then local f = floatItem.text.Font f.Size = 12 floatItem.text.Font = f end
                floatItem.text:SetRenderScale(FVector2D(1.05, 1.05))
                floatItem.text:SetRenderTransformPivot(FVector2D(0.5, 0.5))
                floatItem.text:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                local slot = host:AddChildToCanvas(floatItem.text)
                if slot then
                    slot:SetAutoSize(true)
                    slot:SetAlignment(FVector2D(0.5, 0.5))
                    slot:SetPosition(FVector2D(fX + (fW * 0.5) + 8, fY + fH * 0.5))
                    slot:SetZOrder(12001)
                end
            end
        end)

        -- Click button
        pcall(function()
            floatItem.btn = CGame:NewObjectFromPath("/Script/UMG.Button", host)
            if floatItem.btn and slua.isValid(floatItem.btn) then
                pcall(function() floatItem.btn:SetColorAndOpacity(C.transparent) end)
                pcall(function() floatItem.btn:SetBackgroundColor(C.transparent) end)
                pcall(function() floatItem.btn:SetWidgetVisibility(UEnums.ESlateVisibility.Visible) end)
                local slot = host:AddChildToCanvas(floatItem.btn)
                if slot then
                    slot:SetAutoSize(false)
                    slot:SetPosition(FVector2D(fX, fY))
                    slot:SetSize(FVector2D(fW, fH))
                    slot:SetZOrder(12002)
                end
                pcall(function()
                    if floatItem.btn.OnClicked then
                        floatItem.btn.OnClicked:Add(function()
                            pcall(function()
                                isMenuOpen = not isMenuOpen
                                if isMenuOpen then
                                    if menuBuilt and bgPanel and IsValid(bgPanel) then
                                        ShowMenu()
                                    else
                                        BuildMenu()
                                    end
                                else
                                    HideMenu()
                                end
                            end)
                        end)
                    end
                end)
            end
        end)
    end)
    pcall(ApplyFloatVisibility)
end


-- ===== VIP SKIN POPUP DISABLED =====
_G._SkinPopupShown = true
_G._SkinPopupDone = true
_G._SkinPopupSessionStarted = true
_G._SkinPopupWidgets = nil
-- ===== END SKIN POPUP FUNCTIONS =====

-- ===== SKIN / ITEM AUTHORIZATION BYPASS (ported from 2.lua InitializeSkinBypass) =====
-- The skin-unlock features write client-side depot/list state that the vanilla
-- verification path (AvatarUtils integrity checks, puffer_tlog reporting,
-- FileCheckSubsystem, EquipmentExceptionReport) would otherwise flag or strip.
-- Neutralise those hooks so injected/unowned skins survive. Idempotent.
_G.LexusSkinBypass = function()
    pcall(function()
        local function _nop() return true end
        local _retTrue = function() return true end
        local _retFalse = function() return false end
        local ptlog = package.loaded["client.slua.logic.download.report.puffer_tlog"]
        if ptlog then
            ptlog.ReportEvent = _nop; ptlog.ReportDownloadResult = _nop
            ptlog.ReportODPTDError = _nop; ptlog.ReportSkinError = _nop
        end
        local AvatarUtils = package.loaded["AvatarUtils"]
        if AvatarUtils then
            AvatarUtils.CheckIsWeaponInBlackList = _retFalse
            AvatarUtils.IsValidAvatar = _retTrue
            AvatarUtils.CheckAvatarIntegrity = _retTrue
            AvatarUtils.ReportInvalidAvatar = _nop
        end
        local sub = require("GameLua.GameCore.Module.Subsystem.SubsystemMgr"):Get("FileCheckSubsystem")
        if sub then sub.StartCheck = _nop; sub.ReportAbnormalFile = _nop; sub.StopCheck = _nop end
        local eqEx = package.loaded["client.slua.logic.report.EquipmentExceptionReport"]
        if eqEx then eqEx.Report = _nop; eqEx.SendException = _nop end
    end)
end
pcall(_G.LexusSkinBypass)

-- ===== INIT (robust: works even if no PC/canvas is ready at load) =====
-- Global entry point so other modules / lifecycle hooks can (re)build the
-- floating button. Safe to call at any time; it no-ops while it exists.
_G.ShadowEnsureMenu = function()
    -- Force a fresh canvas lookup so a canvas destroyed on match/lobby
    -- transition is not mistaken for a still-valid one.
    local cur = nil
    pcall(function()
        parentCanvas = nil
        cur = GetCanvas()
    end)
    -- Re-assert the hidden/visible state of the float button on every tick.
    pcall(UpdateMenuButtonPolicy)
    pcall(ApplyFloatVisibility)
    -- Rebuild the menu panel if its host canvas was destroyed/replaced.
    pcall(function()
        if menuBuilt and (not bgPanel or not IsValid(bgPanel) or (cur and menuCanvas ~= cur)) then
            bgPanel = nil
            menuBuilt = false
            allWidgets = {}
            toggleRows = {}
            if isMenuOpen then pcall(BuildMenu) end
        end
    end)
    -- Rebuild the float button if its host canvas was destroyed/replaced.
    if floatItem and floatItem.btn and IsValid(floatItem.btn) and (not cur or floatCanvas == cur) then return end
    floatItem = nil
    pcall(CreateFloat)
end

pcall(function()
    -- Try immediately, then keep a background timer that does NOT depend on a
    -- PlayerController/pawn being valid at load time.
    _G.ShadowEnsureMenu()
    if not _G._ShadowFloatTimer then
        _G._ShadowFloatTimer = Game:SetTimer(2.0, true, function()
            pcall(_G.ShadowEnsureMenu)
        end)
    end

    -- Persistent lifecycle loop (uses common.time_ticker so it survives
    -- match/lobby map transitions): keeps the float/menu alive and re-arms
    -- the hack timers after every match.
    if not _G._ShadowLifecycleLoop then
        local tk = require("common.time_ticker")
        if tk and tk.AddTimerLoop then
            _G._ShadowLifecycleLoop = true
            tk.AddTimerLoop(1.5, function()
                pcall(_G.ShadowEnsureMenu)
                if _G.ShadowEnsureHacks then pcall(_G.ShadowEnsureHacks) end
                if _G.LexusSkinBypass then pcall(_G.LexusSkinBypass) end
            end, -1, 1.5)
        end
    end
end)

end


function M.OnBeginPlay(self)
end
return M

